statement:
Two tables describe students and their study sessions:

- `students(student_id, student_name, major)`: `student_id` is unique.
- `study_sessions(session_id, student_id, subject, session_date, hours_studied)`: one session of one student on one subject; `session_id` is unique, every `student_id` exists in `students`, a student has at most one session per day, and `hours_studied` is a positive decimal.

Line up one student's sessions by `session_date` and let **k** be the number of different subjects among them. The student follows a **study spiral** when all of these hold:

1. k is at least 3;
2. the subjects rotate with period k: every session has the same subject as the session k places before it, so the first k sessions are k different subjects and later sessions repeat them in the same order (a final, unfinished round is fine);
3. there are at least 2k sessions, so the rotation is completed at least twice;
4. no two neighbouring sessions are more than 2 days apart (`DATEDIFF` of at most 2).

Report every such student with the columns `student_id`, `student_name`, `major`, `cycle_length` (k) and `total_study_hours` (the sum of `hours_studied` over all their sessions). Order by `cycle_length` descending, then `total_study_hours` descending, then `student_id` ascending.

validator:
function validate(input) {
  const [{ students = [], study_sessions = [] }] = input;
  const known = new Set(), ids = new Set(), days = new Set(), spelling = new Map();
  for (const [id, name, major] of students) {
    if ([id, name, major].includes(null)) return 'No value in students may be null.';
    if (known.has(id)) return `student_id ${id} appears twice in students.`;
    known.add(id);
  }
  for (const [id, student, subject, day, hours] of study_sessions) {
    if ([id, student, subject, day, hours].includes(null)) return 'No value in study_sessions may be null.';
    if (ids.has(id)) return `session_id ${id} appears twice in study_sessions.`;
    ids.add(id);
    if (!known.has(student)) return `student_id ${student} is not in students.`;
    if (!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(day)) return `session_date ${day} must look like 2023-10-01.`;
    if (days.has(`${student}|${day}`)) return `Student ${student} has two sessions on ${day}.`;
    days.add(`${student}|${day}`);
    if (!(hours > 0 && hours <= 99.99)) return 'hours_studied must be above 0 and at most 99.99.';
    const folded = String(subject).toLowerCase();
    if (spelling.has(folded) && spelling.get(folded) !== subject) return `Subjects ${spelling.get(folded)} and ${subject} differ only in letter case.`;
    spelling.set(folded, subject);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const firsts = ['Alice', 'Bob', 'Carol', 'David', 'Emma', 'Frank', 'Grace', 'Henry'];
  const lasts = ['Chen', 'Johnson', 'Davis', 'Wilson', 'Brown', 'Lee'];
  const majors = ['Computer Science', 'Mathematics', 'Physics', 'Chemistry', 'Biology'];
  const subjects = ['Math', 'Physics', 'Chemistry', 'Biology', 'History', 'Art', 'Music', 'Algebra'];
  const hours = small ? [1, 2, 2.5, 3] : [0.5, 1, 1.25, 1.5, 2, 2.5, 3, 3.75, 4];
  const studentCount = small ? Math.floor(rand() * 4) : 160;
  const students = [];
  for (let id = 1; id <= studentCount; id++) students.push([id, `${pick(firsts)} ${pick(lasts)}`, pick(majors)]);
  const limit = small ? 8 : 1900, rows = [];
  for (const [id] of students) {
    const room = limit - rows.length;
    if (room <= 0) break;
    // A rotation of k subjects, two or more rounds long, sometimes cut short, broken or spread out.
    const k = small ? pick([2, 3, 3, 3, 4]) : 2 + Math.floor(rand() * 5);
    const cycle = [...subjects];
    for (let i = cycle.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [cycle[i], cycle[j]] = [cycle[j], cycle[i]]; }
    let length = rand() < 0.7 ? 2 * k + Math.floor(rand() * (k + 1)) - (rand() < 0.2 ? 1 : 0) : Math.floor(rand() * (2 * k + 1));
    length = Math.min(length, small && id === students[0][0] ? room : Math.min(room, small ? 3 : room));
    const plan = Array.from({ length }, (_, i) => cycle[i % k]);
    if (length > 0 && rand() < 0.2) plan[Math.floor(rand() * length)] = pick(subjects);
    let day = Date.UTC(2024, 1, 15 + Math.floor(rand() * 10));
    for (const subject of plan) {
      rows.push([0, id, subject, new Date(day).toISOString().slice(0, 10), pick(hours)]);
      day += (rand() < (small ? 0.06 : 0.05) ? 3 : 1 + Math.floor(rand() * 2)) * 86400000;
    }
  }
  // session_id does not follow the date order.
  const order = rows.map((_, i) => i + 1);
  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  rows.forEach((row, i) => { row[0] = order[i]; });
  return [{ students, study_sessions: rows }];
}
